"""Apply the authorized audit corrections to the frozen manuscript, not the Vault.

The output is reviewed and written through Obsidian MCP using its current hash.
Original lines and audit IDs make every edit traceable. No new experiment runs.
"""
from pathlib import Path
import hashlib, json, re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'results/v11_corrections_0923'
OUT.mkdir(parents=True, exist_ok=True)
original = (ROOT/'results/v11_claim_audit_0923/manuscript_snapshot.md').read_text()
assert hashlib.sha256(original.encode()).hexdigest() == '8d65672fd89d83f90acf5f7cab8aa472f693659dff9d1f9105e84580cc55b40a'
lines = original.splitlines()
changes = []

def replace_line(n, value, ids):
    old=lines[n-1]
    assert old != value, n
    changes.append({'original_line':n,'audit_ids':ids.split(), 'before':old,'after':value})
    lines[n-1]=value

def sub(n, old, new, ids):
    assert lines[n-1].count(old)==1,(n,old)
    replace_line(n,lines[n-1].replace(old,new),ids)

replace_line(1,'# V11 通し稿（日本語・v1 監査訂正反映版・0923）','T4')
sub(3,'状態: **図表統合版（2026-09-23・Codex）。本文図 1–10・表 1–5・付録 A–J・参考文献を統合。G/H の要確認 4 件は解消。方法の集約・測定定義と比較名の誤記を訂正。【 】は B2・B8 と決定 9 の判断待ちのまま**','状態: **監査訂正反映版（2026-09-23・Codex）。本文・図表説明・付録に事実訂正と主張の限定を反映。反映表は [[V11監査訂正の反映_0923]]。構成は現行のまま、【 】は B2・B8 と決定 9 の判断待ち。B2/B8 は条件を戻した保留文案で、採用を確定していない**','T1 T2 T4')
replace_line(17,'課題を次々に学ぶ設定で、初回には学べていた網が後の課題を学べなくなる可塑性喪失のうち、負側の飽和を介する経路を扱う。各層の前活性を、入力平均への投影で決まる共通位置と入力ごとの揺らぎに分けると、特徴を学ぶ同じ重みの更新が共通位置も動かす幾何が現れる。乱数ラベル CIFAR の raw・ReLU MLP では、入力中心化 C に両隠れ層出力の中心化 H を加えると、50 課題の後期再学習成績が 0.113 から 0.987 へ上がった。さらに第 1 層の bias を除き第 2 層の bias を減衰させた CHB は、200 課題まで全 10 seed で性能を保持した。別の std・ELU 条件では、第 2 層の沈下の主窓の帳簿は自己・上流・交差項の混合となり、両層の重みの成長に上限を置くと後期成績が 10.1% から 86.0% へ上がった。調べた 50 課題では、固定尺度の ReLU・ELU・GELU・SiLU が低成績となり、leaky 群には早期から後期への低下が残る一方、kunekune・適応 Snake は高成績を保った。ELU/std の第 2 層の応答場を人工的に交換すると、次課題の精度が復元で +46.7 pt、沈降で −67.9 pt 変わった。ただし主復元は Adam 継続、主沈降は両腕の Adam 履歴初期化という別条件である。実ラベルの 5+1 CIFAR でも kunekune と適応 Snake は上位群に入り、原典の λ を用いた L2 Init に 19/20 seed で勝ち、この MLP で調整した λ とは登録帯 ±0.5 pt で同等だった。主な対象は二隠れ層 MLP・Adam の三つの課題設定であり、各接続を三設定すべてで検証したとは主張しない。','G3 G4 A2 A4 R1 T5')
sub(25,lines[24].split('【',1)[1].split('】',1)[0], 'B2・B8 保留・監査後の文案: 共有重みの更新は、更新に使わなかった入力の前活性にも作用する。固定入力・一標本の通常 SGD では、非負の入力同士への作用は同符号になるが、実際の Adam 更新の向きはバッチ内の寄与と履歴を含めて判定する。正味の変位が下向きなら正側に届く入力が減り得る。ReLU の負側では、その入力から当該ユニットへの現在の生勾配寄与はゼロになるが、再進入には他の入力の寄与、上流の変化、bias の更新、最適化器の履歴などが関わる。これだけでは入力ごとの不可逆な侵食を意味しない。','T1 T2')
replace_line(27,'層入力の実平均を厳密にゼロにすれば、重みの更新が入力平均への投影を介して共通位置を動かす項は消えるが、bias の経路は残る。実験の H は両隠れ層の出力から EMA 平均を引く操作であり、各時点の実平均を厳密にゼロにするわけではない。入力中心化も加えた CH は 50 課題では高成績を保った。200 課題では CH の登録 COLLAPSE が 7/10（性能と深さの両方 6、深さのみ 1）となり、第 1 層 bias の除去と第 2 層 bias の減衰を加えた CHB は全 10 seed で性能を保持した。総合判定は INCONCLUSIVE であり、b₂ の減衰だけの独立効果を同定した比較ではない。','G3 G4')
sub(29,'入力平均の大きい層では、駆動はまずほぼ全ユニットを負側へ沈める（全部ではない）。向きを決めるのは正側と負側の傾きの非対称であり、活性化を原点のまわりで反転させた鏡像では逆向きに動く。深さは負側の傾きで変わる。','入力平均の大きい層で負側への移動を観測し、別設定の鏡像対照では活性化を原点のまわりで反転させると移動方向も反転した。これは傾きの非対称性の関与を支持するが、全設定で駆動の符号を保証する命題ではない。','T1 G6')
sub(29,'両方の層の負側に傾きが残る網では、失う量は沈んだ深さと床の浅さで決まり、有界にとどまる。片方の層にだけ傾きを残しても足りない。','raw CIFAR の層別キメラでは、比較した 7 セルのうち両層 leaky 0.1 の腕だけが生存基準を満たし、片層を ELU に替えると後期成績が大きく下がった。前向きの値と微分の作用は未分離であり、微分の床だけの必要性、深さと床だけで決まる喪失量、長時間の非崩壊は示していない。','A1')
sub(31,'輸送によって課題に必要な応答が失われ、その再形成や他のユニットによる補償でも埋め合わせられなくなると、新しい課題を学ぶ能力が低下する。','本稿では応答の減少と、その再形成・維持の制約を機構の作業仮説として区別する。応答場の交換や担い手の追加が再学習成績を変える介入証拠を示す一方、実効数だけで能力を決める必要十分な法則は示していない。','R2 R3')
replace_line(33,'**本稿の貢献。** (1) 前活性の共通位置を入力平均への投影で書く恒等式と、入力・両隠れ層出力の中心化および bias への複合介入が、raw CIFAR・ReLU の有限期間の再学習能力を保つこと（§3）。(2) C 腕 ReLU の課題 2–5 で自己更新の負の正味変位が切替直後に集中するという記述と、別条件 raw・LE の凍結窓介入が初期の上流平均成長を抑えること（§4）。(3) ELU/std の第 2 層の輸送帳簿と、両層の成長上限による後期成績の改善（§5）。(4) 活性化による応答と成績の分岐、および kunekune・適応 Snake が乱数ラベル CIFAR の 50 課題で高成績を保つこと（§6）。(5) 人工的な応答場交換が再学習成績を両方向に変えること（§7）。(6) 実ラベルの 5+1 CIFAR でも Snake 系が上位群に入り、L2 Init と条件を揃えて比較できること（§8）。新規本走の前に固定した判定、既知軌道の登録再解析、登録出力の事後解釈と予測の事後採点を区別する（§10・§11）。','G3 G6 A2 A4 R1 T4 T5')
sub(41,'機能的な可塑性喪失は、訓練で使われる応答を残す（ユニット, 入力）の対が実効的に尽き、かつ輸送が続いてそこから戻れない状態として操作的に判定する。判定の閾値は箱ごとに較正し、絶対値を箱の間で比べない。','応答の枯渇と回復の制約は機構を調べる作業仮説とし、機能的な喪失は各走で定めた予算・窓・online 精度の対照差で判定する。応答指標の閾値や実効数の絶対値は箱の間で同一視しない。','R2 R3')
replace_line(70,'### 3.2 初期片側率と入力の平均・偏差の比','G2')
sub(72,'$r=\\|\\bar x\\|/\\mathrm{rms}\\|x-\\bar x\\|$ は raw で 1.911、std と入力中心化 C で 0.121 である。初期化時に全画像で片側（前活性の符号が一様）になるユニットの割合は、ガウス近似で $2\\Phi(-2.33/r)$ と書ける。',r'$r=\|\bar x\|/\mathrm{rms}\|x-\bar x\|$ の seed 中央値は raw で約 1.90、std で約 0.125、平均画像を引く C では丸め誤差の範囲で 0（約 $9.8\times10^{-17}$）である。初期化時に 1200 枚中 1189 枚以上（99%超）が同じ厳密符号になるユニットの割合を、ガウス近似 $2\Phi(-2.33/r)$ と登録予測帯で評価する。','G2')
sub(72,'書けるのは、raw・std・C の第 1 層の初期片側率は $r$ の式で予言できた、までである。','raw・std・C の第 1 層は近似モデルの登録予測帯と両立したが、8 条件全体の主判定は `L1_MODEL_MISS` だった。式そのものの証明とはしない。','G2')
sub(94,'LN は反対側で死ぬ。全ユニットが正側に出て線形化し、実効階数が 63 から 0 へ潰れる。','LN の第 2 層の出力実効階数の中央値は 63 から 0 へ低下した。ただし保存された符号・微分診断は LN 前の z に基づき、実際の ReLU ゲートを表さないため、正側で線形化したという機構解釈には用いない。','G1')
sub(112,'H（中間層だけ）・CS（分散だけ）・LN（素の LayerNorm）はどれも床のままで、付録 E に回した。','H（中間層だけ）・CS（分散だけ）・LN（素の LayerNorm）は登録救済基準を満たさず、付録 E に回した。','G1')
replace_line(129,'| LN（素の LayerNorm） | 0.2062 | — | — | +44† | 16† | — | 後期成績は CH 未満・出力実効階数の中央値 0 |','G1')
replace_line(146,'| S3（`ch_chb_200_0919`・t181–200） | 総合 `INCONCLUSIVE`（登録 COLLAPSE 7/10 < 9/10） | CH の窓 0.375–0.809。7 本の内訳は性能・深さの両方 6、深さのみ 1。CHB 0.988–0.992（10/10） |','G4')
replace_line(150,'CH は 50 課題を保つが、その間に bias の大きさは増えている（|b₂| の平均絶対値 0.15 → 33.9・図 3）。200 課題では CH の登録 COLLAPSE が 7/10 だった（性能と深さの両方 6、深さのみ 1；t181–200 の online は 0.375–0.809）。この 7/10 を、性能閾値 <0.5 を割った本数とは同一視しない。第 2 層のユニット死亡率は 0 でも、画像・ユニットの対で gate が厳密に 0 となる割合は 85–97% に達する（‖w₂‖ 3.8 → 13–17）。第 1 層 bias を除き第 2 層 bias に decoupled weight decay を掛けた CHB は、全 10 seed で 200 課題の性能を保持した（0.988–0.992）。総合ラベルは `INCONCLUSIVE` で、CH の COLLAPSE 7/10 は登録基準 9/10 に届かない。CHB でも応答の侵食は記録されており、性能保持は応答不変を意味しない。二つの bias 操作と課題 1 から異なる予防履歴をまとめた比較なので、b₂ 減衰だけの独立効果、崩壊後の回復、無限時間の予防、他設定での有効性は主張しない。','G3 G4')
replace_line(167,'同じ扉を実ラベルの 5+1 CIFAR × MLP に移すと、H 単独は std・raw の両方で ReLU に 10/10 で勝った。以下の診断値と水準は std の値である（後期 online 0.424 → 0.546・図 4）。第 2 層の沈下・低応答化が抑えられ（z̄₂ −8.82 → +0.64・死亡率 0.38 → 0・可動度 0.002 → 0.61）、実効階数は 9.1 から 13.5 へ改善したが、kunekune の約 51 や L2 Init の約 38 には届かなかった。raw の H は z̄₂ −1.11・死亡率 0.010 であり、同じ完全停止とは扱わない。これらはゲート以外の表現の違いも残るという事後の示唆で、その独立した因果寄与を二成分に分解した結果ではない。CH は課題 1 の時点で R より 7 pt 低く、予算を 10 倍にした比較では CH − R の符号が反転した（+0.116 → −0.086・付録 B）。増予算の R も fresh gap +0.094 を残す。中心化の効果は課題設定・対象層・予算に依存し、普遍的な処方とはしない。','G5 A6 A7')
sub(192,'したがって、誤差修正の自己駆動は切替の衝撃であり、誤差が消えると正味はほぼ 0 になる。課題の間の沈降は上流（‖µ₂‖ の伸び）が運ぶ。これは §5 の補助窓（課題 10 → 50 で上流が 99%）と両層の上限（S5）と同じ向きである。','C 腕 ReLU の課題 2–5 では、自己更新による負の正味変位は切替直後 75 更新に集中し、後続の自己変位は小さかった。後続でも上流変位は全 5 seed で負だった。これは登録窓の収支の記述であり、誤差消失を操作して自己駆動の消失を同定したものではない。§5 の ELU/std の帳簿や S5 とは別の活性化・入力条件で、単一軌道の機構として連結しない。','G6')
sub(194,'図 6・作図待ち','図 6','G6')
sub(236,'「上流が運ぶ」と言えるのは低応答に達した後の輸送である。','報告のみの固定窓 t10→50 では上流項が 99% を占めるが、低応答到達後のすべての時点にこの比率を外挿しない。A6 は既知軌道に規則を固定した再解析である。','G7 T4')
sub(238,'bias を固定しても上乗せはない（78.85%）。','副腕 cap12_bfix の平均は 78.85% で、cap12 の 85.98% を上回らなかった（副比較の記述）。','G7')
sub(238,r'成長を止めると微分の担い手 $\bar n_{\rm eff}$ が減り、その分だけ応答経由の残りが減る（未使用 seed で r = +0.92）。',r'別の RL-MNIST 実験では、健康な t2 の網に t10 の低応答の動く場を移植した状態で成長を制限すると、$\bar n_{\rm eff}$ と応答の床からの成績の残りがともに減った。減少量の相関は未使用 10 seed 間で r = +0.92 だったが、実効数による比例的な媒介を意味しない。','G7 R4')
sub(264,'その深さの負側ゲートが課題 1 を学べるかを分ける（ELU 0.83・GELU 0.14・SiLU 0.15・ReLU 0.14）。','課題 1 の online 精度は ELU 0.83・GELU 0.14・SiLU 0.15・ReLU 0.14 だった。この対応は負側微分の違いと整合する事後の観測で、ゲートだけの媒介効果を分離した結果ではない。','A2')
sub(264,'床はどちらの層にも要る（LL − LE +0.627・LL − EL +0.589・ともに 10/10）。','LL − LE は +0.627、LL − EL は +0.589（ともに 10/10）である。この raw 条件では両層を leaky .1 とした腕だけが生存基準を満たしたが、前向き値と微分は未分離で、微分の床だけの必要条件とはしない。','A1')
replace_line(266,'**負側に非ゼロの固定傾き（leaky 0.01–0.3・Smooth-Leaky）。** 局所微分は残るが、leaky 0.1 の online 精度は早期 t1–10 から後期 t41–50 へ raw 4.9 pt・std 1.4 pt 低下した。raw の事後診断では片側化も観測されたが、これが劣化を媒介するかは未検証である。後期窓 t31–50 の水準は傾き 0.3 / 0.1 / 0.01 の順に 0.845 / 0.726 / 0.388 だった。これらは後期水準であり、深さと床だけで決まる喪失量や長時間の下げ止まりを示してはいない。','A1 A2 A8')
sub(268,'帯の中に居続けて傾きの切替を保つ。','今回の 50 課題では分布の多くが曲がる領域に残り、初期窓から後期窓への成績低下は見られなかった。幅への追随は中心位置への追随ではなく、適応尺度だけによる非崩壊の保証ではない。','A2')
sub(268,'適応 Snake と同等以上（A `SNA_BEATEN`）。','SNA に raw では優位、std では差を検出しなかった。std の A `SNA_BEATEN` は KKA/KKA23 による判定で、KKT1 の同等性判定ではない。','A4')
sub(268,'周期は要らず（K1）','この条件では繰り返す周期なしでも近い成績を保ち（K1）','A4')
sub(308,'KKT1 が SNA と同等以上','raw では KKT1 が SNA に優位、std の判定は KKA/KKA23 による。KKT1–SNA の std は TIE で、同等性を意味しない','A4')
replace_line(312,'飽和型の経路を調べる作業仮説として、訓練で応答を残す（ユニット, 入力）の対の減少と、その回復・維持の制約を分ける。機能的な喪失は各走の登録予算と online 精度の対照差で判定する。個々の入力の微分が厳密に 0 でも、他の入力や上流、Adam の履歴による更新までゼロとは限らない。MNIST の当該実装では全勾配と残留更新が尽きた凍結を確認した一方、float64 の F.elu でも同じ有限予算で崩壊が再現したため、厳密 0 は崩壊の必要条件ではない。別の PM・leaky の幅の経路では、3 seed・t120 の比較で予算 8 倍による差は 1.8 pt だったが、この有限比較から一般の不可逆性は導かない。','R2 R3')
sub(314,'応答が再学習能力を決めることは、','応答場の変更が再学習成績を変えることは、','R2')
sub(314,'分岐点の特徴・logit・損失・重み・Adam の状態は自然な網と 1 bit も変えない。','応答場の変更自体は分岐点の特徴・logit・損失・重みを保つ。主 P1 は Adam を継続し、主 P2 は両腕の Adam 履歴を初期化する。','R1')
